echo '' | base64 -d > /tmp/aom2.zip
rm -rf /tmp/aom2; mkdir -p /tmp/aom2; unzip -oq /tmp/aom2.zip -d /tmp/aom2
export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/aoutmux2; rm -rf $D; mkdir -p $D; cd $D
cp /tmp/aom2/*.v /tmp/aom2/*.tcl $D/
for t in s_a s_b; do /opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source $t.tcl > $t.log 2>&1; if grep -q "DONE_$t" $t.log; then echo "OK $t"; else echo "FAIL $t"; grep -m3 ERROR $t.log; fi; done
tar czf /tmp/aom2_out.tgz s_a.bit s_a.pips s_b.bit s_b.pips 2>/dev/null || echo NOTAR
echo AOM2DONE
